async () => {
const r=e=>{if(!e)return null; const b=e.getBoundingClientRect(); return {x:Math.round(b.left),y:Math.round(b.top),w:Math.round(b.width),h:Math.round(b.height)};}; const ov=(a,b)=>!!a&&!!b&&!(a.x+a.w<=b.x||b.x+b.w<=a.x||a.y+a.h<=b.y||b.y+b.h<=a.y); const ban=r(document.querySelector('.incoming-call')); const skip=r(document.querySelector('.tutorial-skip')); const prog=r(document.querySelector('.tutorial-progress')); const panel=r(document.querySelector('.tutorial-panel')); const nxt=r(document.querySelector('.tutorial-next')); return {banner:ban, skip, progress:prog, panel, next:nxt, overlapsSkip:ov(ban,skip), overlapsProgress:ov(ban,prog), overlapsPanel:ov(ban,panel), overlapsContinue: nxt&&nxt.w?ov(ban,nxt):null, skipVisible: !!document.querySelector('.tutorial-skip') && document.querySelector('.tutorial-skip').offsetParent!==null};

}

async () => {
const b=document.querySelector('.tutorial-skip'); return b ? (document.elementFromPoint(b.getBoundingClientRect().left+5,b.getBoundingClientRect().top+5)===b ? 'SKIP is topmost at its corner' : 'SKIP covered by '+document.elementFromPoint(b.getBoundingClientRect().left+5,b.getBoundingClientRect().top+5).className) : 'no skip';

}
